shots.draw_js:
clearScene();setBig(null);
setEq("$$d_{t+1} \\;=\\; d_t P \\qquad P[s][s']=P(s'\\mid s)$$","top");
mdpChain({n:2,y:320,r:38,x:480,gap:320,
  label:function(i){return i===0?"A":"B";},
  cls:function(i){return i===0?"y":"b";},
  arcs:[[0,1,"1.0","y",-70],[1,0,"1.0","b",-70]]});
note("分布是行向量，右乘 P",640,432,"sm");
setCap("讲座开头（约 00:07:01）断言「链跑得够久就收敛到平稳分布、与起点无关」。<b>在这条链上它是假的</b>，而前提一个都没说。");

clearScene();setEq(null);
setBig("马尔可夫链会忘掉起点","跑得足够久，从哪出发都一样");
setCap("这个直觉<b>大部分时候是对的</b> —— 这正是它危险的地方。");

clearScene();setBig(null);
setEq("$$d_t(A)\\;=\\;\\Pr(s_t=A)\\qquad d_0=(1,\\,0)$$","top");
lamps({y:320,gap:340,items:[
  {label:"柱子停住",sub:"收敛",state:"on"},
  {label:"柱子一直动",sub:"不收敛",state:"dead"}]});
setCap("读法：横轴是<b>时间</b>，第 t 根柱子是「时刻 t 在 A 的概率」—— 这不是一条轨迹，是<b>概率的演化</b>。");

clearScene();setBig(null);
setEq("$$P=\\begin{pmatrix}0&1\\\\1&0\\end{pmatrix}\\qquad d_0=(1,\\,0)$$","top");
fillBars({vals:[1,0,1,0,1,0,1,0],order:[0,1,2,3,4,5,6,7],step:300,
  x:210,y:420,w:860,h:150,max:1,
  label:function(i){return "t="+i;},
  cls:function(i){return i%2===0?"y":"r";},
  fmt:function(v){return v.toFixed(0);}});
setCap("<b>周期 2</b>：d = (1,0),(0,1),(1,0),… 永远震荡，<b>不收敛</b> —— 起点的奇偶性一步也没被抹掉。");

clearScene();setBig(null);
setEq("$$P=\\begin{pmatrix}0.9&0.1\\\\0.2&0.8\\end{pmatrix}\\qquad d_0=(1,\\,0)$$","top");
fillBars({vals:[1,0.9,0.83,0.781,0.747,0.723,0.706,0.694],order:[0,1,2,3,4,5,6,7],step:300,
  x:210,y:420,w:860,h:150,max:1,
  label:function(i){return "t="+i;},
  cls:function(i){return "b";},
  fmt:function(v){return v.toFixed(3);}});
setCap("<b>非周期且不可约</b>：d_t(A) = 2/3 + (1/3)·0.7^t → 0.667。偏离量按 0.7 的幂衰减，这次真的收敛。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:290,items:[
  {label:"不可约",sub:"哪儿都到得了",state:"on"},
  {label:"非周期",sub:"回到自身 gcd=1",state:"on"},
  {label:"有限状态",sub:"Perron–Frobenius",state:"on"}]});
setCap("<b>指名反驳</b>：随机性不是充分条件。三者齐备才有<b>唯一平稳分布 + 与起点无关</b>的收敛。（本讲共 <b>19 处</b>跳过的证明，本片逐处标注。）");

clearScene();setBig(null);
setEq("$$V(s)\\;=\\;R(s)+\\gamma\\sum_{s'}P(s'\\mid s)\\,V(s')$$","top");
lamps({y:320,gap:300,items:[
  {label:"蒙特卡洛",sub:"误差 ~ N^(−1/2)",state:"off"},
  {label:"闭式解",sub:"|S|³ 一次到位",state:"off"},
  {label:"迭代 DP",sub:"每轮 |S|²",state:"off"}]});
setCap("同一个 V，三条求法。<b>差别不在正确性，在代价与可迁移性</b>。");

clearScene();setEq(null);
setBig("有闭式解就该用闭式解","迭代是没有解析解时的退而求其次");
setCap("这个排序在数值分析课上通常是对的 —— <b>精确解优于迭代解</b>。");

clearScene();setBig(null);
setEq("$$V\\;=\\;R+\\gamma P V \\;\\Longrightarrow\\; (I-\\gamma P)V=R \\;\\Longrightarrow\\; V=(I-\\gamma P)^{-1}R$$","top");
mdpChain({n:7,y:320,r:26,x:230,gap:130,
  label:function(i){return "s"+(i+1);},
  rew:function(i){return i===0?"+1":(i===6?"+10":"0");},
  cls:function(i){return i===6?"g":(i===0?"y":"");}});
note("γ = 0.9，右移概率 0.5",640,430,"sm");
setCap("统一的试验台：<b>7 格火星车走廊</b>，奖励只有两端非零，固定策略「一直向右」。");

clearScene();setBig(null);
setEq("$$V_{k+1}(s)\\;\\leftarrow\\; R(s)+\\gamma\\sum_{s'}P(s'\\mid s)\\,V_k(s')\\qquad V_0=\\mathbf{0}$$","top");
fillBars({vals:[0,0,0,0,0,0,10],order:[6,5,4,3,2,1,0],step:260,
  x:210,y:420,w:860,h:150,max:100,
  label:function(i){return "s"+(i+1);},
  cls:function(i){return i===6?"g":"";},
  fmt:function(v){return v.toFixed(2);}});
setCap("<b>V₁</b>：一轮扫描只走了一步 —— 只有 s₇ 和 s₁ 知道自己拿了奖励，其余六个仍是 0。");

clearScene();setBig(null);
setEq("$$V_5 \\quad\\text{（第 5 轮扫描后）}$$","top");
fillBars({vals:[1.79,0,0.41,2.96,10.18,23.11,40.95],order:[6,5,4,3,2,1,0],step:260,
  x:210,y:420,w:860,h:150,max:100,
  label:function(i){return "s"+(i+1);},
  cls:function(i){return i===6?"g":(i<=2?"r":"");},
  fmt:function(v){return v.toFixed(2);}});
setCap("<b>V₅</b>：锋面推进到 s₃ 附近就熄灭了。柱顶数字：s₃=0.41 很小但非零，s₂=0.00 精确为零。");

clearScene();setBig(null);
setEq("$$V_{\\infty}\\;=\\;(I-\\gamma P)^{-1}R \\qquad \\text{与迭代到收敛的结果逐位相同}$$","top");
bars({vals:[31.82,36.67,44.81,54.77,66.94,81.82,100.00],
  x:210,y:420,w:860,h:150,max:100,
  label:function(i){return "s"+(i+1);},
  cls:function(i){return i===6?"g":"b";},
  fmt:function(v){return v.toFixed(2);}});
setCap("<b>收敛值</b>：V(s₇) = 10/(1−0.9) = 100，正是 R_max/(1−γ) 那个界取到等号。三条路算的确实是同一个 V。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:290,items:[
  {label:"只对固定策略",sub:"有 max 就非线性",state:"dead"},
  {label:"|S|³ 求逆",sub:"稍大就不可行",state:"dead"},
  {label:"迭代能往下走",sub:"加 max、去模型",state:"on"}]});
setCap("<b>指名反驳</b>：闭式解是这一讲的终点，<b>迭代是整门课的起点</b> —— 它此后再没出现过。");

clearScene();setBig(null);
setEq("$$V=(I-\\gamma P)^{-1}R$$","top");
note("默认了 (I − γP) 可逆",640,320,"ink lg");
note("什么时候真的不可逆",640,380,"y lg");
setCap("课上有学生问了，讲座「先记下，回头答」，约 00:41:08 才用一句谱半径带过 —— <b>而那句话也没证</b>。");

clearScene();setEq(null);
setBig("可逆性是个数值问题","大多数时候没事，碰到病态就换算法");
setCap("这个模型对<b>随机取来的矩阵</b>是对的。但 <b>I − γP 不是随机取来的</b>。");

clearScene();setBig(null);
setEq("$$\\sum_{s'}P(s'\\mid s)=1\\quad\\text{对每个 }s \\qquad\\Longleftrightarrow\\qquad P\\mathbf{1}=\\mathbf{1}$$","top");
note("全 1 向量是 P 的特征向量",640,320,"y lg");
note("特征值恰为 1",640,380,"g lg");
setCap("这不是巧合也不是近似 —— 它就是「概率加起来等于 1」这句话本身。由此一行得到 ρ(P) ≤ ‖P‖_∞ = 1。");

clearScene();setBig(null);
setEq("$$(I-\\gamma P)\\mathbf{1}\\;=\\;\\mathbf{1}-\\gamma P\\mathbf{1}\\;=\\;\\mathbf{1}-\\gamma\\mathbf{1}\\;=\\;(1-\\gamma)\\mathbf{1}$$","top");
bars({vals:[0.5,0.3,0.2,0.1],
  x:330,y:410,w:620,h:150,max:0.5,
  label:function(i){return ["γ=0.5","γ=0.7","γ=0.8","γ=0.9"][i];},
  cls:function(i){return "b";},
  fmt:function(v){return v.toFixed(2);}});
setCap("柱高 = (1−γ)。再往下画不出来：γ=0.99 时是 0.01（约 3px），<b>γ=1 时精确为 0</b>。");

clearScene();setBig(null);
setEq("$$\\gamma=1:\\qquad (I-P)\\mathbf{1}=\\mathbf{0} \\qquad\\Longrightarrow\\qquad I-P \\text{ 奇异}$$","top");
note("非零向量被映成零",640,320,"r lg");
note("解相差一个常数",640,380,"y lg");
setCap("<b>γ = 1 时 I − P 精确奇异</b>：给所有状态同加常数 c，方程依然成立 ⟹ 解不唯一 ⟹ 不可能有逆。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:340,items:[
  {label:"γ < 1",sub:"1 − γλ ≠ 0",state:"on"},
  {label:"γ = 1",sub:"(I−P)·1 = 0",state:"dead"}]});
note("条件数 ~ 1/(1−γ)",640,420,"sm");
setCap("<b>指名反驳</b>：不是「通常可逆偶尔病态」，是 γ <b>一个参数完全决定</b>的二分 —— 与 P 的具体数值无关。");
